from collections.abc import Callable
from typing import Literal, get_args

from .jsontypes import Json, JsonObject
from .toolkit import ToolType, is_tool

Field = Literal[
    "org_id",
    "invoice_id",
    "invoice_month",
    "line_items",
    "amounts",
    "request_ids",
    "response_status",
    "time_of_issue",
    "checks_done",
    "plan",
    "contract",
    "error_code",
    "billing_period",
    "timezone",
]
