    content: str | None = None
    role: str = "user"
    tool_calls: list[ToolCall] | None = None
@dataclass
class AssistantMessage(_Turn):
    content: str | None = None
    role: str = "assistant"
    tool_calls: list[ToolCall] | None = None
    usage: dict[str, int] | None = None
@dataclass
